
(function () {
  // The card this replaces is an instance of the "Icon + Tagline Card"
  // component, which has ten instances across the site and exposes no slot
  // prop — so there is nowhere inside the instance to put an embed. Instead the
  // embed sits at page level and adopts the slot from outside: it finds the
  // image, hides it, and mounts itself in the image's place.
  //
  // Every step fails safe. If the markup ever moves, nothing is found, nothing
  // is hidden, and the page keeps the SVG it has today rather than showing a
  // hole where the shot should be.
  function findImage() {
    var row = document.querySelector('.brief-design_row');
    if (!row) return null;
    var images = row.querySelectorAll('img.icon-tagline_card-image');
    // Prefer the Plan card by name, so re-ordering the columns cannot silently
    // point this at the Build or Grow card. Fall back to the first column,
    // which is where the Plan card lives today.
    for (var i = 0; i < images.length; i++) {
      if ((images[i].getAttribute('src') || '').indexOf('card-plan') !== -1) {
        return images[i];
      }
    }
    return images[0] || null;
  }

  var img = findImage();
  if (!img || img.dataset.rpaAdopted) return;
  img.dataset.rpaAdopted = '1';

  // Hidden, not removed: restoring the original is clearing this one property.
  img.style.display = 'none';

  var mount = document.createElement('div');
  mount.setAttribute('data-relume-plan-asset', '');
  mount.className = 'rpa';
  img.parentNode.insertBefore(mount, img.nextSibling);

  var style = document.createElement('style');
  style.textContent = ".rpa{display:block;position:relative;z-index:1;width:100%}\n.rpa-stage{position:relative;width:100%;aspect-ratio:374/349;overflow:hidden}\n.rpa-board{position:absolute;top:0;left:0;width:374px;height:349px;transform:scale(var(--rpa-scale,1));transform-origin:top left}\n.rpa{--duration:.2s;--ease:ease;--font-size-lg:1rem;--font-size-md:.875rem;--font-size-xl:1.25rem;--font-weight-medium:500;--font-weight-normal:400;--radius-lg:calc(4px * 3);--radius-sm:calc(4px * 1.5);--spacing-2xl:calc(4px * 12);--spacing-2xs:4px;--spacing-default:calc(4px * 2);--spacing-lg:calc(4px * 6);--spacing-md:calc(4px * 4);--spacing-sm:calc(4px * 3);--spacing-xl:calc(4px * 8)}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__frame{--plan-panel-bg: #f1f0ee; --plan-ink: #101010; --plan-accent: #ff00f4; --plan-border-subtle: #1b19191a; --plan-border-button: #1616161a; --plan-button-ink: #161616; --plan-ink-muted: #8a8a8a; --plan-panel-edge: #fff; --plan-font: \"Geist Variable\", Geist, sans-serif; --plan-frame-width: 374px; --plan-frame-height: 349px; box-sizing: border-box; width: var(--plan-frame-width); height: var(--plan-frame-height); font-family: var(--plan-font); color: var(--plan-ink); -webkit-font-smoothing: antialiased; font-variation-settings: normal; align-items: flex-end; display: flex; position: relative; overflow: hidden;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__frame *, .rpa .frontend-base-marketing-plan_asset-plan_asset__frame ::before, .rpa .frontend-base-marketing-plan_asset-plan_asset__frame ::after{box-sizing: border-box;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__window{border-top-right-radius: var(--radius-lg); flex-shrink: 0; width: 330px; height: 309px; position: relative; overflow: hidden;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__panel{justify-content: center; align-items: flex-start; gap: var(--spacing-2xl); box-sizing: border-box; width: 918px; height: 5568px; padding: var(--spacing-2xl) 20px; background: var(--plan-panel-bg); border-radius: var(--radius-lg); box-shadow: inset 0 0 0 1px var(--plan-panel-edge); display: flex; position: absolute; top: 0px; right: 0px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__content{flex-direction: column; flex-shrink: 0; align-items: flex-start; width: 660px; max-width: 660px; display: flex;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__quickLink{flex-direction: column; flex-shrink: 0; width: 170px; display: flex;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__headerRow{justify-content: space-between; align-items: center; width: 100%; height: 32px; display: flex;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__headerTitle, .rpa .frontend-base-marketing-plan_asset-plan_asset__sectionHeading{font-size: var(--font-size-xl); letter-spacing: -0.2px; color: var(--plan-ink); margin: 0px; font-weight: 440; line-height: 1.4;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__headerTitle{flex: 1 1 0%; min-width: 0px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__sectionHeadingRow{align-items: center; width: 100%; display: flex; overflow: hidden;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__sectionHeading{flex: 1 1 0%; min-width: 0px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__editButton{justify-content: flex-start; align-items: center; gap: var(--spacing-2xs); box-sizing: border-box; width: 108px; height: 32px; padding: 0 var(--spacing-sm); border-radius: var(--radius-sm); box-shadow: inset 0 0 0 1px var(--plan-border-button); flex-shrink: 0; display: flex;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__editButtonIcon{width: 20px; height: 20px; color: var(--plan-ink); flex-shrink: 0; justify-content: center; align-items: center; display: flex;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__editButtonLabel{font-size: var(--font-size-md); font-weight: var(--font-weight-medium); white-space: nowrap; color: var(--plan-button-ink); line-height: 20px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__section{gap: var(--spacing-md); box-sizing: border-box; width: 100%; padding: var(--spacing-lg) 0; flex-direction: column; display: flex;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__sectionRuled{padding: var(--spacing-xl) 0; box-shadow: inset 0 -1px 0 0 var(--plan-border-subtle);}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__bodyLarge{width: 100%; font-size: var(--font-size-lg); font-weight: var(--font-weight-normal); color: var(--plan-ink); margin: 0px; line-height: 24px; position: relative; top: 1px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__bodyBase, .rpa .frontend-base-marketing-plan_asset-plan_asset__bullets{width: 100%; font-size: var(--font-size-md); font-weight: var(--font-weight-normal); color: var(--plan-ink); margin: 0px; line-height: 20px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__bullets{padding: 0px; list-style: outside;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__bullets li{margin-inline-start: 21px; margin-bottom: var(--spacing-2xs);}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__bullets li:last-child{margin-bottom: 0px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__quickItem{box-sizing: border-box; width: 100%; padding: var(--spacing-default) var(--spacing-md); box-shadow: inset 2px 0 0 0 var(--plan-border-subtle); transition: box-shadow var(--duration) var(--ease); align-items: center; display: flex;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__quickItemActive{box-shadow: inset 2px 0 0 0 var(--plan-accent);}\n@media (hover: hover) and (pointer: fine){.rpa .frontend-base-marketing-plan_asset-plan_asset__quickItem:not(.frontend-base-marketing-plan_asset-plan_asset__quickItemActive):hover{box-shadow: inset 2px 0 0 0 var(--plan-ink);}}\n@media (hover: hover) and (pointer: fine){.rpa .frontend-base-marketing-plan_asset-plan_asset__quickItem:not(.frontend-base-marketing-plan_asset-plan_asset__quickItemActive):hover .frontend-base-marketing-plan_asset-plan_asset__quickItemLabel{color: var(--plan-ink);}}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__quickItemLabel{font-size: var(--font-size-md); font-weight: var(--font-weight-normal); color: var(--plan-ink-muted); transition: color var(--duration) var(--ease); margin: 0px; line-height: 20px;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__quickItemActive .frontend-base-marketing-plan_asset-plan_asset__quickItemLabel{color: var(--plan-ink);}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__fitHost{aspect-ratio: 374 / 349; width: 100%; position: relative; overflow: hidden;}\n.rpa .frontend-base-marketing-plan_asset-plan_asset__fitHost > .frontend-base-marketing-plan_asset-plan_asset__frame{transform: scale(var(--plan-asset-scale, 1)); transform-origin: 0px 0px;}\n.p-theme-dark .rpa .frontend-base-marketing-plan_asset-plan_asset__frame{--plan-panel-bg: #101010; --plan-ink: #fff; --plan-button-ink: #fff; --plan-border-subtle: #ffffff0f; --plan-border-button: #ffffff0f; --plan-panel-edge: #ffffff0f;}";
  document.head.appendChild(style);

  var stage = document.createElement('div');
  stage.className = 'rpa-stage';
  var board = document.createElement('div');
  board.className = 'rpa-board';
  board.innerHTML = "<div class=\"frontend-base-marketing-plan_asset-plan_asset__frame\"><div class=\"frontend-base-marketing-plan_asset-plan_asset__window\"><div class=\"frontend-base-marketing-plan_asset-plan_asset__panel\"><div class=\"frontend-base-marketing-plan_asset-plan_asset__content\"><div class=\"frontend-base-marketing-plan_asset-plan_asset__headerRow\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__headerTitle\">Overview</p><div class=\"frontend-base-marketing-plan_asset-plan_asset__editButton\"><span class=\"frontend-base-marketing-plan_asset-plan_asset__editButtonIcon\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"14\" height=\"14\" fill=\"none\" viewBox=\"0 0 14 14\"><g fill=\"currentColor\"><path d=\"M8.594.901a1.514 1.514 0 0 1 2.141 0L13.1 3.266c.592.591.592 1.55 0 2.141l-7.046 7.046a.6.6 0 0 1-.306.164l-4.572.914a.599.599 0 0 1-.705-.706l.914-4.571.023-.085a.602.602 0 0 1 .14-.222L8.595.901Zm1.293.849a.314.314 0 0 0-.445 0L2.524 8.667l-.703 3.512 3.512-.704L12.25 4.56a.314.314 0 0 0 0-.445L9.887 1.75Z\"></path><path d=\"M1.548 7.948a.599.599 0 0 1 .848 0l3.657 3.656a.6.6 0 0 1-.849.849L1.548 8.796a.599.599 0 0 1 0-.848ZM6.92 2.577a.599.599 0 0 1 .847 0l3.657 3.656a.6.6 0 0 1-.848.848L6.918 3.424a.599.599 0 0 1 0-.847Z\"></path></g></svg></span><span class=\"frontend-base-marketing-plan_asset-plan_asset__editButtonLabel\">Edit brief</span></div></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__section\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__bodyLarge\">An independent, Australian-owned 4PL logistics provider founded in 1991 (35+ years). Headquartered in Ringwood, Melbourne, Myfreight manages freight across Australia and New Zealand through a network of 100+ carriers. They don't own trucks: they design, procure, and manage tailored carrier mixes for mid-to-large businesses, supported by proprietary freight management software. Formerly Poste-Haste, rebranded in 2015.</p></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__section\"><div class=\"frontend-base-marketing-plan_asset-plan_asset__sectionHeadingRow\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__sectionHeading\">Goals</p></div><ul class=\"frontend-base-marketing-plan_asset-plan_asset__bullets\"><li>Win enterprise-scale logistics tenders and RFPs with a credible, modern digital presence</li><li>Shift perception from a boutique freight consultant to a serious enterprise-grade 4PL partner with the scale, systems, and track record procurement teams look for</li><li>Surface credentials that enterprise buyers require: ISO certifications, chain of responsibility accreditations, scale (100+ carrier network, national coverage), industry awards, and named enterprise client outcomes</li><li>Speak directly to government and construction procurement audiences alongside existing retail/industrial/wholesale sectors</li></ul></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__section frontend-base-marketing-plan_asset-plan_asset__sectionRuled\"><div class=\"frontend-base-marketing-plan_asset-plan_asset__sectionHeadingRow\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__sectionHeading\">Target audience</p></div><p class=\"frontend-base-marketing-plan_asset-plan_asset__bodyBase\">Enterprise procurement and supply-chain decision-makers at government agencies and construction firms (plus retail, industrial, wholesale, e-commerce) evaluating logistics partners through formal tender processes. They look for scale, compliance certifications, track record, financial stability, DIFOT performance data, and demonstrated ability to handle complex multi-site national operations.</p></div></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__quickLink\"><div class=\"frontend-base-marketing-plan_asset-plan_asset__quickItem frontend-base-marketing-plan_asset-plan_asset__quickItemActive\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__quickItemLabel\">Overview</p></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__quickItem\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__quickItemLabel\">Goals</p></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__quickItem\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__quickItemLabel\">Target audience</p></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__quickItem\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__quickItemLabel\">Key requirements</p></div><div class=\"frontend-base-marketing-plan_asset-plan_asset__quickItem\"><p class=\"frontend-base-marketing-plan_asset-plan_asset__quickItemLabel\">Supporting docs</p></div></div></div></div></div>";
  stage.appendChild(board);
  mount.appendChild(stage);

  // The image this replaces was width:100% / height:100% in its wrapper, so the
  // shot has to fill the slot the same way — at every breakpoint, and scaling up
  // as well as down, because the row is three columns wide on desktop and one
  // below that.
  //
  // Scaling resamples every 1px stroke in the shot, and neighbouring strokes
  // landing on different sub-pixel offsets is what reads as uneven stroke
  // weight, so land the artboard on a whole number of device pixels. Nothing is
  // left on a rasterised layer once this settles: the transform is a static
  // scale, never an animation, so the strokes stay as crisp as the scale allows.
  function resize() {
    var dpr = window.devicePixelRatio || 1;
    var raw = stage.clientWidth / 374;
    var scale = Math.round(374 * raw * dpr) / (374 * dpr);
    board.style.setProperty('--rpa-scale', scale);
  }
  resize();
  new ResizeObserver(resize).observe(stage);
})();
